<?php
declare(strict_types=1);require_once __DIR__.'/bootstrap.php';learning_require_login();$pdo=learning_pdo();$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT * FROM learning_mock_tests WHERE id=?");$s->execute([$id]);$m=$s->fetch();if(!$m)exit('Mock test not found.');$s=$pdo->prepare("SELECT q.* FROM learning_mock_questions mq JOIN learning_questions q ON q.id=mq.question_id WHERE mq.mock_test_id=? ORDER BY mq.sort_order");$s->execute([$id]);$qs=$s->fetchAll();$s=$pdo->prepare("SELECT * FROM learning_options WHERE question_id IN(SELECT question_id FROM learning_mock_questions WHERE mock_test_id=?) ORDER BY sort_order");$s->execute([$id]);$opts=[];foreach($s as $o)$opts[$o['question_id']][]=$o;
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=eh($m['title'])?></title><style>body{margin:0;background:#080a10;color:#fff;font-family:Inter,system-ui}.wrap{max-width:850px;margin:auto;padding:30px 18px}.card{padding:22px;border:1px solid #fff1;border-radius:15px;background:#10151e}.q{padding:14px 0;border-bottom:1px solid #fff1}.opt{display:block;padding:9px;border:1px solid #fff1;border-radius:8px;margin:5px 0;font-size:9px}.btn{margin-top:15px;padding:11px 14px;border:0;border-radius:8px;background:linear-gradient(135deg,#8b5cf6,#22d3ee);color:#fff;font-weight:850}</style></head><body><div class="wrap"><div class="card"><h1><?=eh($m['title'])?></h1><div style="font-size:8px;color:#788398"><?=$m['question_count']?> Questions · <?=$m['time_limit_minutes']?> Minutes</div><form id=f><?php foreach($qs as $i=>$q):?><div class=q><strong style="font-size:10px"><?=$i+1?>. <?=eh($q['question'])?></strong><?php foreach($opts[$q['id']]??[] as $o):?><label class=opt><input type=radio name="q[<?=$q['id']?>]" value="<?=$o['id']?>"> <?=eh($o['option_text'])?></label><?php endforeach;?></div><?php endforeach;?><button class=btn>Submit</button></form><div id=r style="margin-top:15px;font-size:10px"></div></div></div><script>f.onsubmit=async e=>{e.preventDefault();let a={};new FormData(f).forEach((v,k)=>{let m=k.match(/q\[(\d+)\]/);if(m)a[m[1]]=v});let z=await fetch('mock-api.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mock_id:<?=$id?>,answers:a})});let x=await z.json();r.textContent=x.ok?`Score ${x.score}/${x.total} · ${x.percent}% · ${x.passed?'PASSED':'FAILED'} · +${x.xp} XP`:x.error}</script></body></html>